@torch.no_grad()
def generar_sin_cache(modelo, idx, n):
    for _ in range(n):
        logits = modelo(idx)[:, -1]
        idx = torch.cat([idx, logits.argmax(-1, keepdim=True)], dim=1)
    return idx

